  animation: fadeIn 0.4s ease-out forwards;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.stepEmoji {
  font-size: 64px;
}

.stepTitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-primary);
}

.stepDesc {
  font-size: var(--font-size-md);
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.stepperWrapper {
  margin-top: var(--spacing-lg);
  background: white;
  padding: var(--spacing-md);
  border-radius: var(--radius-lg);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
}

.payrollFooter {
  padding: var(--spacing-lg);
  padding-bottom: calc(var(--safe-area-bottom) + var(--spacing-lg));
}import { useState } from 'react';
import ReactECharts from 'echarts-for-react';
import { useFinanceStore } from '../../stores/financeStore';
import { RecordSheet } from './RecordSheet';
import { PayrollGuidance } from './PayrollGuidance';
import styles from './index.module.css';

const Dashboard = () => {
  const store = useFinanceStore();
  const [recordVisible, setRecordVisible] = useState(false);
  const [payrollVisible, setPayrollVisible] = useState(false);

  // 组装给 ECharts 的数据集
  const chartData = store.budgets.map((b) => ({
    name: b.name,
    value: b.spentAmount,
    color: b.color,
    percent: Math.min(100, Math.round((b.spentAmount / b.totalAmount) * 100)),
  }));

  const ringChartOption = {
    color: chartData.map((d) => d.color),
    series: chartData.map((d, idx) => {
      // 动态分布多层圆环的半径
      const outRadius = 85 - idx * 18;
      const inRadius = outRadius - 10;
      return {
        type: 'pie',
        radius: [`${inRadius}%`, `${outRadius}%`],
        center: ['50%', '50%'],
        startAngle: 90,
        label: { show: false },
        data: [
          { value: d.percent, name: d.name, itemStyle: { borderRadius: 10 } },
          { value: 100 - d.percent, itemStyle: { color: '#EFEFEF' } },
        ],
      };
    }),
  };

  return (
    <div className={`page-container ${styles.container}`}>
      <header className={styles.header}>
        <div className={styles.headerIconWrapper}>
          <span className={styles.headerIcon}>⚙️</span>
        </div>
        <h1 className={styles.headerTitle}>您的财务报告</h1>
        <div className={styles.headerIconWrapper}>
          <span className={styles.headerIcon}>📤</span>
        </div>
      </header>

      <section className={styles.sectionHeader}>
        <h2 className={styles.sectionTitle}>财务健康结果</h2>
        <p className={styles.sectionSubtitle}>
          财务状况通过记账数据的分析揭示健康财富流
        </p>
      </section>

      <div className={styles.scoreRow}>
        <div className={styles.scoreIconBox}>
          <span className={styles.scoreIcon}>🌿</span>
        </div>
        <div className={styles.scoreTextCol}>
          <div className={styles.scoreTextTitle}>为您的财务状况评分</div>
          <div className={styles.scoreTextDate}>
            最近发薪：
            {new Date(store.profile.lastPayrollDate).toLocaleDateString()}
          </div>
        </div>
      </div>

      <div className={styles.metricsGrid}>
        <div className={styles.metricCard}>
          <div className={styles.metricLabel}>可支配资金</div>
          <div className={styles.metricValue}>
            ¥{store.disposableIncome.toLocaleString()}
          </div>
        </div>
        <div className={styles.metricCard}>
          <div className={styles.metricLabel}>估算生存周期</div>
          <div className={styles.metricValue}>
            {Math.floor(store.disposableIncome / 200)}
            <span style={{ fontSize: '16px', marginLeft: 2 }}>天</span>
          </div>
        </div>
      </div>

      <section className={styles.statsSection}>
        <div className={styles.statsHeader}>
          <h2 className={styles.sectionTitle}>预算执行统计</h2>
          <span className={styles.statsIcon}>📊</span>
        </div>

        <div className={styles.statsBody}>
          <div className={styles.progressBars}>
            {chartData.map((d) => (
              <div className={styles.progressItem} key={d.name}>
                <div className={styles.progressLabel}>{d.name}</div>
                <div className={styles.progressPercent}>{d.percent}%</div>
                <div className={styles.progressBarTrack}>
                  <div
                    className={styles.progressBarFill}
                    style={{ width: `${d.percent}%`, backgroundColor: d.color }}
                  ></div>
                </div>
              </div>
            ))}
          </div>

          <div className={styles.ringChartContainer}>
            <ReactECharts
              option={ringChartOption}
              style={{ height: '200px', width: '200px' }}
              opts={{ renderer: 'svg' }}
            />
          </div>
        </div>
      </section>

      <section className={styles.overviewSection}>
        <h2 className={styles.sectionTitle}>您的财务概览</h2>
        <p className={styles.overviewText}>
          健康的财务不仅仅是账面的数字，还反映了整体的生活质量。它的特点是现金流稳定、预算分配合理、浪费率低。您当前的净资产预估为{' '}
          <strong>¥{store.profile.netWorth.toLocaleString()}</strong>。
        </p>
      </section>

      <div className={styles.actionButtons}>
        <button
          type="button"
          className={`${styles.btn} ${styles.btnOutline}`}
          onClick={() => setPayrollVisible(true)}
        >
          发薪重配
        </button>
        <button
          type="button"
          className={`${styles.btn} ${styles.btnSolid}`}
          onClick={() => setRecordVisible(true)}
        >
          记一笔
        </button>
      </div>

      {/* 挂载交互弹窗 */}
      <RecordSheet
        visible={recordVisible}
        onClose={() => setRecordVisible(false)}
      />
      <PayrollGuidance
        visible={payrollVisible}
        onClose={() => setPayrollVisible(false)}
      />
    </div>
  );
};

export default Dashboard;import { useState } from 'react';
import { Popup, Stepper, Dialog } from 'antd-mobile';
import { useFinanceStore } from '../../stores/financeStore';
import styles from './index.module.css';

interface PayrollGuidanceProps {
  visible: boolean;
  onClose: () => void;
}

export const PayrollGuidance = ({ visible, onClose }: PayrollGuidanceProps) => {
  const [step, setStep] = useState(1);
  const [payrollAmount, setPayrollAmount] = useState(15000);
  const processPayroll = useFinanceStore((s) => s.processPayroll);

  const handleNext = () => {
    if (step === 1) {
      setStep(2);
    } else if (step === 2) {
      setStep(3);
    } else {
      // Done - process
      processPayroll(payrollAmount, new Date().toISOString());
      Dialog.alert({
        content: '发薪已处理，资金已注入可用余额池，尽情分配吧！',
        onConfirm: () => {
          setStep(1);
          onClose();
        },
      });
    }
  };

  return (
    <Popup
      visible={visible}
      position="right"
      bodyStyle={{ width: '100vw', backgroundColor: '#F9F9FB' }}
    >
      <div className={styles.payrollContainer}>
        <div className={styles.payrollHeader}>
          <button onClick={onClose} className={styles.closeBtn}>
            ×
          </button>
          <div className={styles.stepIndicator}>Step {step} of 3</div>
        </div>

        <div className={styles.payrollBody}>
          {step === 1 && (
            <div className={styles.stepCard}>
              <div className={styles.stepEmoji}>🎉</div>
              <h2 className={styles.stepTitle}>又发薪了！本月收入多少？</h2>
              <div className={styles.stepperWrapper}>
                <Stepper
                  value={payrollAmount}
                  onChange={(v) => setPayrollAmount(v || 0)}
                  step={100}
                  min={0}
                  style={{
                    '--button-font-size': '24px',
                    '--input-font-size': '28px',
                  }}
                />
              </div>
            </div>
          )}

          {step === 2 && (
            <div className={styles.stepCard}>
              <div className={styles.stepEmoji}>🛡️</div>
              <h2 className={styles.stepTitle}>系统自动拦截预扣资源</h2>
              <p className={styles.stepDesc}>
                已按设定规则锁定应急资金：¥1,000
              </p>
              <p className={styles.stepDesc}>已预扣固定支出：无</p>
            </div>
          )}

          {step === 3 && (
            <div className={styles.stepCard}>
              <div className={styles.stepEmoji}>💧</div>
              <h2 className={styles.stepTitle}>可支配池注水完成</h2>
              <p className={styles.stepDesc}>
                剩余 ¥{(payrollAmount - 1000).toLocaleString()} <br />
                已准备好分配至各项预算容器中。
              </p>
            </div>
          )}
        </div>

        <div className={styles.payrollFooter}>
          <button
            className={`${styles.btn} ${styles.btnSolid}`}
            onClick={handleNext}
          >
            {step === 3 ? '完成注入' : '下一步'}
          </button>
        </div>
      </div>
    </Popup>
  );
};import { useState } from 'react';
import { Popup, NumberKeyboard, Toast } from 'antd-mobile';
import { useFinanceStore } from '../../stores/financeStore';
import styles from './index.module.css';

interface RecordSheetProps {
  visible: boolean;
  onClose: () => void;
}

const CATEGORIES = [
  { id: 'b1', name: '饮食', icon: '🍔' },
  { id: 'b2', name: '日用', icon: '🛒' },
  { id: 'b3', name: '交通', icon: '🚗' },
  { id: 'b4', name: '娱乐', icon: '🎉' },
  { id: 'other', name: '其他', icon: '📂' },
];

export const RecordSheet = ({ visible, onClose }: RecordSheetProps) => {
  const [amount, setAmount] = useState('0');
  const [selectedCategoryId, setSelectedCategoryId] = useState(
    CATEGORIES[0].id,
  );
  const addTransaction = useFinanceStore((s) => s.addTransaction);

  const handleInput = (v: string) => {
    if (v === 'BACKSPACE') {
      setAmount((prev) => (prev.length > 1 ? prev.slice(0, -1) : '0'));
    } else {
      setAmount((prev) => (prev === '0' ? v : prev + v));
    }
  };

  const handleConfirm = () => {
    const num = parseFloat(amount);
    if (!num || num <= 0) {
      Toast.show('请输入有效金额');
      return;
    }

    addTransaction({
      type: 'expense',
      amount: num,
      categoryId: selectedCategoryId,
      date: new Date().toISOString(),
      memo: '',
      tags: [],
      subItems: [],
    });

    Toast.show({ icon: 'success', content: '记账成功' });
    setAmount('0');
    onClose();
  };

  return (
    <Popup
      visible={visible}
      onMaskClick={onClose}
      bodyStyle={{
        borderTopLeftRadius: '24px',
        borderTopRightRadius: '24px',
        backgroundColor: '#fff',
      }}
    >
      <div className={styles.sheetContainer}>
        <div className={styles.amountDisplay}>
          <span className={styles.currencySymbol}>¥</span>
          <span className={styles.amountValue}>{amount}</span>
        </div>

        <div className={styles.categoryScroll}>
          {CATEGORIES.map((cat) => {
            const isActive = selectedCategoryId === cat.id;
            return (
              <div
                key={cat.id}
                className={`${styles.categoryPill} ${isActive ? styles.activePill : ''}`}
                onClick={() => setSelectedCategoryId(cat.id)}
              >
                <div className={styles.categoryIcon}>{cat.icon}</div>
                <div className={styles.categoryName}>{cat.name}</div>
              </div>
            );
          })}
        </div>

        <NumberKeyboard
          visible={true}
          customKey={'.'}
          confirmText="完成"
          onClose={handleConfirm}
          onInput={handleInput}
          onDelete={() => handleInput('BACKSPACE')}
          className={styles.customKeyboard}
        />
      </div>
    </Popup>
  );
};.container {
