.lotQty {
  font-size: var(--font-size-xs);
  color: var(--color-accent);
  font-weight: 600;
}

.lotExpInfo {
  font-size: 10px;
  color: var(--color-text-tertiary);
  margin-top: var(--spacing-sm);
  display: flex;
  justify-content: space-between;
