/* ========================
   全局样式 - 紫罗兰浅色极简风格 (仿参考图)
   ======================== */

:root {
  /* 主色调 */
  --color-bg: #ffffff;
  --color-bg-card: #f7f7fd; /* 极浅紫色背景卡片 */
  --color-bg-elevated: #ffffff;
