  /* 文字 */
  --color-text-primary: #1a1a1a;
  --color-text-secondary: #7a7a8c;
  --color-text-tertiary: #a1a1b5;

  /* 功能色 */
  --color-accent: #6c5dd3; /* 紫色主色调 */
  --color-accent-light: #8b80f9;
  --color-success: #34d399;
  --color-warning: #fbbf24;
  --color-danger: #f87171;

  /* 间距 */
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;

  /* 圆角 */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  /* 字体 */
  --font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue",
    Arial, sans-serif;
  --font-size-xs: 12px;
  --font-size-sm: 14px;
  --font-size-md: 16px;
  --font-size-lg: 20px;
  --font-size-xl: 24px;
  --font-size-xxl: 28px;

  /* 安全区域 */
  --safe-area-bottom: env(safe-area-inset-bottom, 0px);
  --tabbar-height: 60px;
}

/* Reset */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--color-accent);
  text-decoration: none;
}

ul,
ol {
  list-style: none;
}

input,
button,
textarea {
  font-family: inherit;
  font-size: inherit;
  border: none;
  outline: none;
  background: none;
}

/* Ant Design Mobile 主色覆盖 */
:root:root {
  --adm-color-primary: var(--color-accent);
  --adm-color-success: var(--color-success);
  --adm-color-warning: var(--color-warning);
  --adm-color-danger: var(--color-danger);
  --adm-color-background: var(--color-bg);
  --adm-color-text: var(--color-text-primary);
  --adm-color-text-secondary: var(--color-text-secondary);
  --adm-font-family: var(--font-family);
}

/* 页面容器 - 底部给 TabBar 留空间 */
.page-container {
  padding: var(--spacing-lg) var(--spacing-md);
  padding-bottom: calc(
    var(--tabbar-height) +
    var(--safe-area-bottom) +
    var(--spacing-xl)
  );
  min-height: 100vh;
}export type TransactionType =
  | 'income'
  | 'expense'
  | 'refund'
  | 'budget_overflow';

export interface SubItem {
  id: string;
  name: string;
  amount: number;
  isInventory: boolean;
  isConsumable: boolean;
  shelfLifeDays?: number; // 对于消耗品的保质期（天）
}

export interface Transaction {
  id: string;
  type: TransactionType;
  amount: number;
  categoryId: string;
  date: string; // ISO string 留存
  timestamp: number;
  memo: string;
  tags: string[];
  subItems: SubItem[];
}

export interface BudgetBlock {
  id: string;
  name: string;
  totalAmount: number; // 目标额度
  spentAmount: number; // 已消耗额度
  icon: string;
  color: string;
  isEmergency?: boolean;
}

// --- Inventory 模块重构的新实体 ---

export type StorageMode = 'room_temperature' | 'refrigerated' | 'frozen';
export type StockEventType = 'stock_in' | 'consume' | 'discard' | 'change_storage';

export interface Station {
  id: string;
  name: string;
  recommendedMode: StorageMode;
  icon: string;
}

export interface InventoryItemTemplate {
  id: string;
  name: string;
  baseUnit: string; // 基础单位如 ml, g, piece
  defaultStorageMode: StorageMode;
  defaultShelfLifeDays: number; // 默认保质期
  icon: string;
}

export interface StockLot {
  id: string;
  itemId: string;        // 关联到模板
  stationId: string;     // 关联到物理存放区域
  storageMode: StorageMode; // 最终该批次的实际存放方式
  initialQuantity: number;
  remainingQuantity: number;
  purchaseDate: string;  // ISO Date
  expireDate: string;    // ISO Date
  remark: string;
}

export interface StockEvent {
  id: string;
  lotId: string;
  type: StockEventType;
  quantityChange: number; // 改变了多少数量
  previousStationId?: string; // 转移时的原区域
  timestamp: string;      // ISO String
  reason?: string;        // discard 等的理由
}

export interface UserProfile {
  name: string;
  avatarUrl: string;
  netWorth: number;
  payrollCycleDays: number;
  monthlyIncomePrediction: number; // 预估月薪
  lastPayrollDate: string;
  emergencyFundEnabled: boolean;
